package mod.cdv.tnpc.tactical;import java.util.*;import net.neoforged.neoforge.registries.DeferredRegister;import net.neoforged.neoforge.common.DeferredSpawnEggItem;import net.minecraft.world.item.component.CustomData;import net.neoforged.neoforge.event.BuildCreativeModeTabContentsEvent;public class EggChecks22{static int checks;static void ok(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}public static class Bus{public Class<?> subscriber;public void register(Class<?> c){subscriber=c;}}public static void main(String[]a){var bus=new Bus();EggRegistration.install(bus);ok(DeferredRegister.entries.size()==4,"four separately registered egg items");ok(DeferredRegister.entries.containsKey("bandit_spawn_egg"),"old egg ID remains valid");ok(bus.subscriber==EggRegistration.class&&DeferredRegister.subscribed&&CalmWorldEvents.installed,"registrations and existing world hooks installed");var colors=new HashSet<Integer>();for(int i=0;i<4;i++){var egg=(DeferredSpawnEggItem)DeferredRegister.entries.get(EggRegistration.IDS[i]).get();var nbt=((CustomData)egg.properties.components.get("entity_data")).tag();ok(nbt.getString("id").equals("tacznpcs:npc"),"egg spawns native NPC type");ok(nbt.getInt("npc22_role")==i&&nbt.getString("template").equals("__tactical_role_"+i),"explicit role carried in entity-data component");ok(egg.type.get()==mod.cdv.tnpc.entity.AutoGunOperator.NPC_TYPE,"deferred NPC type resolves");colors.add(egg.base);}ok(colors.size()==4,"four visually distinct egg colors");var event=new BuildCreativeModeTabContentsEvent();EggRegistration.creative(event);ok(event.entries.size()==4,"all four in creative and search tabs");mod.cdv.tnpc.data.TemplateDataManager.TEMPLATES.put("bandits",new Object());for(int i=0;i<4;i++)ok(EggRegistration.resolveTemplate("__tactical_role_"+i).equals("bandits"),"spawn sentinel resolves a real loaded template");ok(EggRegistration.resolveTemplate("__tactical_bandit").equals("bandits"),"legacy sentinel still supported");ok(EggRegistration.resolveTemplate("custom_template").equals("custom_template"),"unrelated templates unchanged");System.out.println("REAL_EGG_REGISTRATION_ENTITY_COMPONENT_COLORS_CREATIVE_TEMPLATE_CHECKS="+checks);}}
